pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint64 number, uint64 timestamp, uint256 basefee, bytes32 hash, uint64 seq, bytes32 batcher, uint256 overhead, uint256 scalar) public {
        vm.assume(actor != address(0));
        address before = c.depositorAccount();
        vm.prank(actor);
        bool ok;
        try c.setL1BlockValues(number, timestamp, basefee, hash, seq, batcher, overhead, scalar) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: for every admissible input, setL1BlockValues never alters
        // the observable depositorAccount value, regardless of whether the call
        // succeeds or reverts. The mutant stores msg.sender into depositorAccount,
        // so when its call succeeds (ok == true) the getter returns `actor`,
        // breaking the invariant for some fuzzed caller.
        assertTrue(c.depositorAccount() == before);
    }
}

